def close_duplicate_open_shifts(apps, schema_editor):
    """MIG-005/CMD-082: retain one OPEN shift per facility/cashier.

    Losing duplicates are closed with explicit evidence; no shift row is
    deleted. The newest (last opened) shift remains open.
    """

    CashierShift = apps.get_model("billing", "CashierShift")
    seen = set()
    shifts = CashierShift.objects.filter(status="OPEN").order_by(
        "facility_id", "cashier_id", "-opened_at", "-id"
    )
    for shift in shifts.iterator():
        key = (shift.organisation_id, shift.facility_id, shift.cashier_id)
        if key in seen:
            shift.status = "CLOSED"
            shift.closed_at = shift.opened_at
            shift.close_reason = "MIG-005 duplicate open shift closed during S-05 reconciliation"
            shift.save(update_fields=["status", "closed_at", "close_reason"])
        else:
            seen.add(key)


def _receipt_hash(payment, allocations):
    envelope = {
        "payment_id": str(payment.id),
        "receipt_no": payment.receipt_no,
        "amount": str(payment.amount),
        "method": payment.method,
        "received_at": payment.received_at.isoformat(),
        "allocations": [
            {"invoice_id": str(allocation.invoice_id), "amount": str(allocation.amount)}
            for allocation in allocations
        ],
    }
    return hashlib.sha256(
        json.dumps(envelope, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode("utf-8")
    ).hexdigest()


def backfill_s05(apps, schema_editor):
    """MIG-006/008/009 deterministic evidence; never invent a split or credit."""

    Payment = apps.get_model("billing", "Payment")
    PaymentAllocation = apps.get_model("billing", "PaymentAllocation")
    PaymentReceipt = apps.get_model("billing", "PaymentReceipt")
    Invoice = apps.get_model("billing", "Invoice")
    InvoiceItem = apps.get_model("billing", "InvoiceItem")

    for payment in Payment.objects.all().order_by("id").iterator():
        if payment.status == "POSTED":
            payment.status = "CONFIRMED"
            payment.save(update_fields=["status"])
        allocations = list(
            PaymentAllocation.objects.filter(payment_id=payment.id).order_by("invoice_id")
        )
        if not allocations and payment.invoice_id is not None and payment.amount > 0:
            invoice = Invoice.objects.filter(id=payment.invoice_id).first()
            if invoice is not None and invoice.status not in {"VOID", "VOIDED"}:
                allocation = PaymentAllocation.objects.create(
                    organisation_id=payment.organisation_id,
                    facility_id=payment.facility_id,
                    payment_id=payment.id,
                    invoice_id=invoice.id,
                    amount=payment.amount,
                )
                allocations = [allocation]
        if not allocations:
            # Missing allocation evidence stays visible for MIG-008
            # reconciliation; it is never fabricated as a split.
            continue
        if not PaymentReceipt.objects.filter(payment_id=payment.id).exists():
            PaymentReceipt.objects.create(
                organisation_id=payment.organisation_id,
                facility_id=payment.facility_id,
                payment_id=payment.id,
                receipt_no=payment.receipt_no,
                content_hash=_receipt_hash(payment, allocations),
                issued_at=payment.received_at,
                issued_by_id=payment.received_by_id,
            )

    for invoice in Invoice.objects.all().order_by("id").iterator():
        if invoice.status in {"VOID", "VOIDED"}:
            continue
        subtotal = sum(
            (
                line.amount
                for line in InvoiceItem.objects.filter(invoice_id=invoice.id, state="ACTIVE")
            ),
            Decimal("0.00"),
        ).quantize(Decimal("0.01"))
        discount = min(invoice.discount, subtotal).quantize(Decimal("0.01"))
        total = (subtotal - discount).quantize(Decimal("0.01"))
        applied = PaymentAllocation.objects.filter(
            invoice_id=invoice.id,
            payment__status__in=("CONFIRMED", "POSTED"),
        )
        applied_total = sum(
            (allocation.amount for allocation in applied), Decimal("0.00")
        ).quantize(Decimal("0.01"))
        balance = max(Decimal("0.00"), total - applied_total).quantize(Decimal("0.01"))
        if total > 0 and balance == 0:
            status = "PAID"
        elif applied_total > 0:
            status = "PARTIALLY_PAID"
        else:
            status = "ISSUED" if invoice.issued_at else invoice.status
        Invoice.objects.filter(id=invoice.id).update(
            subtotal=subtotal,
            discount=discount,
            total=total,
            amount_paid=applied_total,
            balance=balance,
            status=status,
        )


